<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import {Users,Plus,RefreshCw,Search,X,History,ShieldCheck,UserRoundCog,UserRoundMinus,ChevronLeft,ChevronRight,GraduationCap,UserRoundCheck} from 'lucide-vue-next';
const memberIcon:Record<string,any>={STUDENT:Users,ASSISTANT:UserRoundCheck,TEACHER:GraduationCap};
import {api} from './api';
const props=defineProps<{courseId:number}>();const emit=defineEmits(['changed']);
const data=ref<any>(null),query=ref(''),role=ref(''),page=ref(1),tab=ref('list'),records=ref<any[]>([]),loading=ref(false),error=ref(''),busy=ref(false),actionError=ref(''),conflict=ref(false),status=ref('');const dialog=ref<HTMLDialogElement>(),mode=ref('add'),target=ref<any>(null),email=ref(''),newRole=ref('STUDENT'),reason=ref(''),editRevision=ref(0);let generation=0,timer:ReturnType<typeof setTimeout>,returnFocus:HTMLElement|null=null;
const roleNames:Record<string,string>={TEACHER:'教师',ASSISTANT:'助教',STUDENT:'学生'};const actionNames:Record<string,string>={ADD:'添加成员',ROLE:'调整身份',REMOVE:'移出课程'};
const totalPages=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/20)));const count=(key:string)=>data.value?.counts?.find((x:any)=>x.role===key)?.total||0;
function date(v:string){return new Date(v).toLocaleString('zh-CN',{hour12:false});}
async function load(){const g=++generation;loading.value=true;error.value='';try{const q=new URLSearchParams({q:query.value,role:role.value,page:String(page.value)});const d=await api(`/courses/${props.courseId}/members?${q}`);if(g!==generation)return;data.value=d;if(page.value>1&&!d.members.length){page.value=Math.max(1,Math.ceil(d.total/20));await load();}}catch(e:any){if(g===generation)error.value=e.message;}finally{if(g===generation)loading.value=false;}}
function search(){clearTimeout(timer);page.value=1;timer=setTimeout(load,250);}
async function history(){loading.value=true;error.value='';try{records.value=await api(`/courses/${props.courseId}/members/history`);}catch(e:any){error.value=e.message;}finally{loading.value=false;}}
function open(kind:string,row?:any){if(!data.value||loading.value)return;returnFocus=document.activeElement as HTMLElement;mode.value=kind;target.value=row?{...row}:null;email.value='';newRole.value=row?.role||'STUDENT';reason.value='';editRevision.value=data.value.revision;actionError.value='';conflict.value=false;dialog.value?.showModal();}
function close(force=false){if(busy.value)return;if(!force&&(email.value||reason.value||newRole.value!==(target.value?.role||'STUDENT'))&&!confirm('放弃本次未保存的成员管理输入？'))return;dialog.value?.close();returnFocus?.focus();}
async function reloadConflict(){if(!confirm('重新载入将关闭本次操作并放弃当前输入。请核对最新成员身份后重新操作。'))return;close(true);await load();}
async function submit(){if(busy.value||conflict.value)return;if(mode.value!=='add'&&!reason.value.trim()){actionError.value='请填写操作原因';return;}if(mode.value==='remove'&&!confirm(`确认将 ${target.value.display_name}（${target.value.email}）移出本课程？作品与评价不删除，但该账号将失去本课访问权限。`))return;busy.value=true;actionError.value='';try{const root=`/courses/${props.courseId}/members`;if(mode.value==='add')await api(root,'POST',{email:email.value.trim(),role:newRole.value,reason:reason.value.trim()||'教师添加已有账号',revision:editRevision.value});else await api(`${root}/${target.value.id}/${mode.value==='role'?'role':'remove'}`,'POST',{...(mode.value==='role'?{role:newRole.value}:{}),reason:reason.value,revision:editRevision.value});status.value=mode.value==='remove'?'成员已移出；作品、提交和评价历史已保留。':mode.value==='role'?'成员身份已更新。':'已有账号已加入课程。';busy.value=false;close(true);await load();emit('changed');}catch(e:any){actionError.value=e.message;conflict.value=e.status===409;}finally{busy.value=false;}}
function unload(e:BeforeUnloadEvent){if(dialog.value?.open&&(email.value||reason.value||busy.value)){e.preventDefault();e.returnValue='';}}
onMounted(()=>{load();window.addEventListener('beforeunload',unload);});onBeforeUnmount(()=>{generation++;clearTimeout(timer);window.removeEventListener('beforeunload',unload);});
</script>
<template><section class="page members-page"><div class="page-heading"><div><span class="eyebrow">课程组织与权限</span><h1>课程成员</h1><p>管理已有账号的课程身份，保留作品与教学记录。</p></div><div class="button-row"><button class="btn secondary" :disabled="loading" @click="tab==='list'?load():history()"><RefreshCw :size="15"/>刷新列表</button><button class="btn primary" :disabled="loading||!data" @click="open('add')"><Plus :size="16"/>添加已有账号</button></div></div>
<div class="member-stats"><article v-for="key in ['STUDENT','ASSISTANT','TEACHER']" :key="key" class="stat-card"><i class="stat-icon"><component :is="memberIcon[key]" :size="17"/></i><span>{{ roleNames[key] }}</span><strong>{{ count(key) }}</strong><small>{{ key==='TEACHER'?'任课教师身份受保护':key==='ASSISTANT'?'课程辅助与只读评审':'创作、提交与修订' }}</small></article></div>
<p v-if="status" class="member-status" role="status">{{ status }}</p><p v-if="error" class="notice-error" role="alert">{{ error }}</p><div class="members-toolbar"><div class="list-tabs"><button :class="{active:tab==='list'}" @click="tab='list';load()"><Users :size="15"/>成员列表</button><button :class="{active:tab==='history'}" @click="tab='history';history()"><History :size="15"/>操作记录</button></div><div v-if="tab==='list'" class="member-filters"><label class="member-search"><Search :size="15"/><input v-model="query" maxlength="80" aria-label="搜索课程成员" placeholder="搜索姓名或邮箱" @input="search"/></label><select v-model="role" aria-label="按成员身份筛选" @change="page=1;load()"><option value="">全部身份</option><option value="STUDENT">学生</option><option value="ASSISTANT">助教</option><option value="TEACHER">教师</option></select></div></div>
<div v-if="tab==='list'" class="card member-list" :aria-busy="loading"><div class="member-table-head"><span>姓名 / 邮箱</span><span>课程身份</span><span>操作</span></div><article v-for="m in data?.members||[]" :key="m.id" class="member-row" :data-member-id="m.id"><div class="member-person"><span class="avatar">{{ m.display_name.slice(0,1) }}</span><div><strong>{{ m.display_name }}</strong><p>{{ m.email }}</p></div></div><span class="member-role" :class="m.role.toLowerCase()">{{ roleNames[m.role] }}</span><div v-if="m.role==='TEACHER'" class="member-protected"><ShieldCheck :size="14"/>教师身份受保护</div><div v-else class="member-actions"><button class="text-btn" :disabled="loading" @click="open('role',m)"><UserRoundCog :size="14"/>调整身份</button><button class="text-btn muted" :disabled="loading" @click="open('remove',m)"><UserRoundMinus :size="14"/>移出课程</button></div></article><div v-if="!loading&&!data?.members.length" class="empty"><Users :size="28"/><h2>没有匹配的成员</h2><p>试试其他姓名、邮箱或身份筛选。</p></div><p v-if="loading" class="empty-text">正在读取成员…</p><footer v-if="data" class="member-pagination"><span>{{ data.total }} 位成员 · 第 {{ page }} / {{ totalPages }} 页</span><div><button class="btn secondary" :disabled="page<=1||loading" @click="page--;load()"><ChevronLeft :size="14"/>上一页</button><button class="btn secondary" :disabled="page>=totalPages||loading" @click="page++;load()">下一页<ChevronRight :size="14"/></button></div></footer></div>
<div v-else class="card member-history"><p class="muted">最近 100 次成员变更</p><article v-for="r in records" :key="r.id"><div><strong>{{ actionNames[r.action_type] }} · {{ r.target_name }}</strong><span>r{{ r.revision_no }}</span></div><p>{{ r.target_email }} · {{ r.before_role?roleNames[r.before_role]:'未加入' }} → {{ r.after_role?roleNames[r.after_role]:'已移出' }}</p><p class="member-history-reason">{{ r.reason }}</p><small>{{ r.actor_name }} · {{ date(r.created_at) }}</small></article><p v-if="!loading&&!records.length" class="empty-text">还没有成员操作记录。更早的初始成员可能未记录原因。</p></div>
<Teleport to="body"><dialog ref="dialog" class="member-dialog" aria-labelledby="member-dialog-title" @cancel.prevent="close()"><header><h2 id="member-dialog-title">{{ mode==='add'?'添加已有账号':mode==='role'?'调整成员身份':'移出课程成员' }}</h2><button class="icon-btn" aria-label="关闭成员操作" :disabled="busy" @click="close()"><X :size="20"/></button></header><form @submit.prevent="submit"><p v-if="actionError" class="notice-error" role="alert">{{ actionError }}</p><button v-if="conflict" type="button" class="btn secondary" @click="reloadConflict">重新载入成员列表</button><fieldset :disabled="busy||conflict"><label v-if="mode==='add'">账号邮箱<input v-model="email" type="email" maxlength="160" required autocomplete="off" placeholder="填写已开通的平台账号邮箱"/></label><div v-else class="member-target"><strong>{{ target?.display_name }}</strong><p>{{ target?.email }}</p></div><label v-if="mode!=='remove'">课程身份<select v-model="newRole" aria-label="新的课程身份"><option value="STUDENT">学生</option><option value="ASSISTANT">助教</option></select></label><p v-if="mode!=='add'" class="management-help">{{ mode==='remove'?'移出后停止本课访问，历史作品、评分和核验记录仍保留。':'助教可辅助查看本课提交，但不能正式发分、管理成员或继续学生作答。' }}</p><label>操作原因<textarea v-model="reason" maxlength="1000" rows="3" :required="mode!=='add'" placeholder="说明添加、身份调整或移出的原因"/></label></fieldset><footer><button type="button" class="btn secondary" :disabled="busy" @click="close()">取消</button><button type="submit" class="btn primary" :disabled="busy||conflict||(mode==='role'&&newRole===target?.role)">{{ busy?'正在保存…':mode==='remove'?'确认移出':mode==='role'?'保存身份':'加入课程' }}</button></footer></form></dialog></Teleport>
</section></template>
